#!/usr/bin/env python3
"""Adds a random minecart to scenarios generated by tools/fuzz.py, which places blocks only.

    tools/fuzz.py --palette tests/palettes/minecart.json --count 30 --size 7x2x7 --ticks 60 \\
                  --seed 1 --out tests/scenarios/minecart
    tests/palettes/minecart-entities.py --seed 1 tests/scenarios/minecart/fuzz-minecart-s1-*.json

The minecart is a function of the seed and the scenario's name only. It is put on a rail of the
scenario when there is one (two times out of three), otherwise anywhere above the floor, with a
random velocity, kind and load. TNT minecarts are left out: they explode when they run into
something, and explosions are not modelled.
"""

import argparse
import json
import os
import random
import sys

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "tools"))
import fuzz  # noqa: E402  (for the output format)

KINDS = ["minecart", "minecart", "minecart", "chest_minecart", "furnace_minecart", "hopper_minecart",
         "spawner_minecart", "command_block_minecart"]
ITEMS = [("minecraft:stone", 64), ("minecraft:ender_pearl", 16), ("minecraft:iron_sword", 1), ("minecraft:redstone", 64)]


def minecart(scenario, rng):
    lo, hi = scenario["box"]["min"], scenario["box"]["max"]
    rails = [b["pos"] for b in scenario.get("blocks", []) if "rail[" in b["state"]]
    if rails and rng.random() < 2 / 3:
        x, y, z = rng.choice(rails)
        pos = [x + 0.5, y + 0.0625, z + 0.5]
    else:
        pos = [round(rng.uniform(lo[0] + 0.5, hi[0] + 0.5), 3), rng.choice([1.0, 1.0625, 1.5, 2.25, 3.0]),
               round(rng.uniform(lo[2] + 0.5, hi[2] + 0.5), 3)]
    speed = rng.choice([0.0, 0.02, 0.1, 0.3, 0.4, 0.9])
    motion = [round(rng.uniform(-speed, speed), 3), rng.choice([0.0, 0.0, -0.1, 0.25]), round(rng.uniform(-speed, speed), 3)]
    if rng.random() < 0.5:
        motion[rng.choice([0, 2])] = 0.0
    kind = rng.choice(KINDS)
    nbt = ["Motion:[%rd,%rd,%rd]" % tuple(float(v) for v in motion)]
    if rng.random() < 0.3:
        nbt.append("Rotation:[%rf,0.0f]" % float(rng.choice([-180, -90, 45, 90, 135, 270, 359.5])))
    if rng.random() < 0.2:
        nbt.append("FlippedRotation:1b")
    if kind in ("chest_minecart", "hopper_minecart"):
        slots = rng.sample(range(5), rng.randint(0, 3))
        stacks = []
        for slot in sorted(slots):
            item, size = rng.choice(ITEMS)
            stacks.append('{Slot:%db,id:"%s",count:%d}' % (slot, item, rng.randint(1, size)))
        nbt.append("Items:[" + ",".join(stacks) + "]")
        if kind == "hopper_minecart" and rng.random() < 0.3:
            nbt.append("Enabled:0b")
    if kind == "furnace_minecart":
        nbt.append("PushX:%rd" % round(rng.uniform(-1, 1), 2))
        nbt.append("PushZ:%rd" % round(rng.uniform(-1, 1), 2))
        nbt.append("Fuel:%ds" % rng.choice([0, 5, 40, 3600]))
    return {"type": "minecraft:" + kind, "pos": pos, "nbt": "{" + ",".join(nbt) + "}"}


def main():
    ap = argparse.ArgumentParser(description="Add a random minecart to fuzzed scenarios.")
    ap.add_argument("--seed", type=int, required=True)
    ap.add_argument("files", nargs="+")
    args = ap.parse_args()
    for path in sorted(args.files):
        with open(path) as f:
            scenario = json.load(f)
        rng = random.Random(f"{args.seed}/{scenario['name']}")
        scenario["entities"] = [minecart(scenario, rng)]
        ordered = {k: scenario[k] for k in ("name", "ticks", "box", "settings", "fill", "blocks", "entities", "actions")
                   if k in scenario}
        with open(path, "w") as f:
            f.write(fuzz.dumps(ordered))


if __name__ == "__main__":
    main()
